mapper.select:
SELECT /*+ MAX_EXECUTION_TIME(1000) */ * FROM chat_message
WHERE conversation_id = #{conversationId} AND seq > #{floor} AND seq < #{before}
  AND body LIKE CONCAT('%', #{pattern}, '%') ESCAPE '='
ORDER BY seq DESC LIMIT #{size}

SELECT m.* FROM chat_bookmark b JOIN chat_message m
  ON m.id = b.message_id AND m.conversation_id = b.conversation_id AND m.seq = b.message_seq
WHERE b.owner_id = #{userId} AND b.conversation_id = #{conversationId}
  AND b.message_seq > #{joinedSeq} AND b.message_seq < #{before}
ORDER BY b.message_seq DESC LIMIT #{size}
